                        patronsOf.getOrDefault(p.getId(), List.of()),
                        aliasesOf.getOrDefault(p.getId(), List.of()),
                        new PersonGrades(p.getGrade(), gradesOf.getOrDefault(p.getId(), List.of())), view.getToday(), usedAround))
                .toList());
    }
